fn inl_get_block_material_params_unfused<'a>(
    ctx: &'a Ctx,
    block_type: i32,
    duration: Val<'a, F32>,
    scale: Val<'a, F32>,
) {
    let mut block_type = block_type;
    let mut duration = duration;
    let mut scale = scale;
    let mut value: i32 = 0;
    if block_type == 2_i32 {
        value = (statics::melee__gr__grgreens::yakumono_param(ctx).get()).x28();
    } else {
        value = (statics::melee__gr__grgreens::yakumono_param(ctx).get()).x24();
    }
    (duration).set(fp::fmuls(fp::frsp(value as f64), fns::Ground_801C0498(ctx)));
    (scale).set(fp::fmuls(5.0, fns::Ground_801C0498(ctx)));
}

fn inl_find_block_unfused<'a>(
    ctx: &'a Ctx,
    gp: Ground<'a>,
    item_gobj: HSD_GObj<'a>,
    row: Val<'a, i32>,
    col: Val<'a, i32>,
) -> i32 {
    let mut gp = gp;
    let mut item_gobj = item_gobj;
    let mut row = row;
    let mut col = col;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    {
        i = 0_i32;
        'l1: while i < 5_i32 {
            'c2: {
                {
                    j = 0_i32;
                    'l3: while j < 6_i32 {
                        'c4: {
                            let mut block: grGreens_BlockVars<'a> =
                                (Handle::add((gp).u().greens().x8_blocks(), i)).get(j);
                            if (((block).status() as i32) != 0_i32)
                                && (Handle::addr((block).x10()) == Handle::addr(item_gobj))
                            {
                                (row).set(i);
                                (col).set(j);
                                return 1_i32;
                            }
                        }
                        j = j.wrapping_add(1);
                    }
                }
            }
            i = i.wrapping_add(1);
        }
    }
    return 0_i32;
}

fn inl_getBlock_unfused<'a>(
    ctx: &'a Ctx,
    gp: Ground<'a>,
    i: i32,
    j: i32,
) -> grGreens_BlockVars<'a> {
    let mut gp = gp;
    let mut i = i;
    let mut j = j;
    return (Handle::add((gp).u().greens().x8_blocks(), i)).get(j);
}

